package internal
import("net/http";"testing";"time")
func TestCertificateBackoff(t *testing.T){for _,tt:=range []struct{name string;code,n int;after string;want time.Duration}{{"rate limit ends primary attempt",429,1,"7200",0},{"bound transient attempts",503,3,"",0},{"respect short retry",503,1,"2",2*time.Second},{"do not retry early",503,1,"7200",0},{"invalid retry does not loop",503,1,"invalid",0},{"transient retry",503,1,"",time.Second}}{t.Run(tt.name,func(t *testing.T){r:=&http.Response{StatusCode:tt.code,Header:make(http.Header)};if tt.after!=""{r.Header.Set("Retry-After",tt.after)};if d:=certificateBackoff(tt.n,nil,r);d!=tt.want{t.Fatalf("delay %v; want %v",d,tt.want)}})}}
func TestIssuerCooldown(t *testing.T){now:=time.Now().UTC().Truncate(time.Second);for _,tt:=range []struct{after string;want time.Duration}{{"7200",2*time.Hour},{now.Add(time.Hour).Format(http.TimeFormat),time.Hour},{"invalid",time.Minute}}{r:=&http.Response{Header:make(http.Header)};r.Header.Set("Retry-After",tt.after);if d:=issuerCooldown(r,now);d!=tt.want{t.Fatalf("cooldown %v; want %v",d,tt.want)}}}
